import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"31、【咸】 艮下兑上","description":"横渠易说 - 31、【咸】 艮下兑上","frontmatter":{"title":"31、【咸】 艮下兑上","description":"横渠易说 - 31、【咸】 艮下兑上"},"headers":[],"relativePath":"zh/classics/hengqu/033.md","filePath":"zh/classics/hengqu/033.md"}'),l={name:"zh/classics/hengqu/033.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_31、【咸】-艮下兑上" tabindex="-1">31、【咸】 艮下兑上 <a class="header-anchor" href="#_31、【咸】-艮下兑上" aria-label="Permalink to “31、【咸】 艮下兑上”">​</a></h1><p>咸之为道，以虚受为本，有意于中，则滞于方体而隘矣。拇、腓、股、脢、辅，以一卦通体高下为言。</p><h3 id="彖曰-咸-感也-柔上而刚下-二气感应以相与-止而说-男下女-是以-亨利贞取女吉-也。天地感而万物化生-圣人感人心而天下和平-观其所感而天地万物之情可见矣。" tabindex="-1">彖曰：咸，感也，柔上而刚下，二气感应以相与，止而说，男下女，是以“亨利贞取女吉”也。天地感而万物化生，圣人感人心而天下和平，观其所感而天地万物之情可见矣。 <a class="header-anchor" href="#彖曰-咸-感也-柔上而刚下-二气感应以相与-止而说-男下女-是以-亨利贞取女吉-也。天地感而万物化生-圣人感人心而天下和平-观其所感而天地万物之情可见矣。" aria-label="Permalink to “彖曰：咸，感也，柔上而刚下，二气感应以相与，止而说，男下女，是以“亨利贞取女吉”也。天地感而万物化生，圣人感人心而天下和平，观其所感而天地万物之情可见矣。”">​</a></h3><p>咸，感也，其爻虽相应而词多不吉，顾其时如何耳。说者多以咸恒配天地，殊不知咸自可配天 地，故于序卦独不言咸。咸既可以配天地，则恒亦可以配天地，皆夫妇之道也。咸之为言皆也，故语 咸则非事。“咸感也”，不可止以夫妇之道谓之咸，此一事耳，男女相配，故为咸也。感之道不一：或 以同而感，圣人感人心以道，此是以同也；或以异而应，男女是也，二女同居则无感也；或以相悦而 感，或以相畏而感，如虎先见犬，犬自不能去，犬若见虎则能避之；又如磁石引针，相应而感也。若以 爱心而来者自相亲，以害心而来者相见容色自别。“圣人感人心而天下和平”，是风动之也；圣人老 吾老以及人之老而人欲老其老，此是以事相感也。感如影响，无复先后，有动必感，咸感而应，故曰 咸速也。</p><h3 id="象曰-山上有泽-咸-君子以虚受人。" tabindex="-1">象曰：山上有泽，咸，君子以虚受人。 <a class="header-anchor" href="#象曰-山上有泽-咸-君子以虚受人。" aria-label="Permalink to “象曰：山上有泽，咸，君子以虚受人。”">​</a></h3><p>山上有泽，非交感不能也。感物之善，莫若以虚受人，有所系慕，皆非正吉，故六爻皆以有应不尽卦义而有所讥也。</p><h3 id="初六-咸其拇。-象曰-咸其拇-志在外也。" tabindex="-1">初六，咸其拇。 象曰：“咸其拇”，志在外也。 <a class="header-anchor" href="#初六-咸其拇。-象曰-咸其拇-志在外也。" aria-label="Permalink to “初六，咸其拇。 象曰：“咸其拇”，志在外也。”">​</a></h3><h3 id="六二-咸其腓-凶-居吉。-象曰-虽凶居吉-顺不害也。" tabindex="-1">六二，咸其腓，凶，居吉。 象曰：虽凶居吉，顺不害也。 <a class="header-anchor" href="#六二-咸其腓-凶-居吉。-象曰-虽凶居吉-顺不害也。" aria-label="Permalink to “六二，咸其腓，凶，居吉。 象曰：虽凶居吉，顺不害也。”">​</a></h3><p>居则吉，趋则凶，以男下女为正，咸之道也。</p><h3 id="九三-咸其股-执其随-往吝。-象曰-咸其股-亦不处也-志在随人-所执下也。" tabindex="-1">九三，咸其股，执其随，往吝。 象曰：“咸其股”，亦不处也；志在随人，所执下也。 <a class="header-anchor" href="#九三-咸其股-执其随-往吝。-象曰-咸其股-亦不处也-志在随人-所执下也。" aria-label="Permalink to “九三，咸其股，执其随，往吝。 象曰：“咸其股”，亦不处也；志在随人，所执下也。”">​</a></h3><p>心宁静于此，一向定叠，前纵有何事亦不恤也，休将闲细碎在思虑。易曰：“何思何虑？天下殊 涂而同归，一致而百虑。”天地之道，惟有日月、寒暑之往来，屈伸、动静两端而已，在我精义入神以致 用，则细碎皆不能出其间，在于术内，已过、未来者事着在心，毕竟何益!浮思游想尽去之，惟图向去 日新可也。孔子以富不可求，则曰“从吾所好”，以思为无益，则曰“不如学也”，故于咸三以见此义。</p><h3 id="九四-贞吉-悔亡。憧憧往来-朋从尔思。-象曰-贞吉悔亡-未感害也。-憧憧往来-未光大也。" tabindex="-1">九四，贞吉，悔亡。憧憧往来，朋从尔思。 象曰：“贞吉悔亡”，未感害也。“憧憧往来”，未光大也。 <a class="header-anchor" href="#九四-贞吉-悔亡。憧憧往来-朋从尔思。-象曰-贞吉悔亡-未感害也。-憧憧往来-未光大也。" aria-label="Permalink to “九四，贞吉，悔亡。憧憧往来，朋从尔思。 象曰：“贞吉悔亡”，未感害也。“憧憧往来”，未光大也。”">​</a></h3><p>释氏以感为幻妄，又有憧憧思以求朋者，皆不足道也。 以阳居阴，非躁感于物者也，然体兑性悦，未免乎思以求朋之累也。盖体悦之初，应止之始，己劳于上，朋止于下，故憧憧得朋，未为光大，不持以正则有诌渎之悔。 感非有意，咸三思以求朋，此则不足道。 圣人惟于屈伸有感，能有屈伸，所以得天下之物，何用憧憧以思而求朋!大抵咸卦六爻皆以有应不尽咸道，故君子欲得虚受人，能容以虚，受人之道也。苟晓屈伸，心尽安泰宽裕，盖为不与物校，待彼伸则己屈，然而屈时少，伸时多，假使乱［亡］横逆，亦犹屈少伸多，我尚何伤!日月寒暑往来，正以相屈伸故不相害。尺蠖之屈以求伸，龙蛇之蛰以存身，又精义入神以致用，利用安身以崇德。</p><h3 id="九五-咸其脢-无悔。-象曰-咸其脢-志末也。" tabindex="-1">九五，咸其脢，无悔。 象曰：“咸其脢”，志末也。 <a class="header-anchor" href="#九五-咸其脢-无悔。-象曰-咸其脢-志末也。" aria-label="Permalink to “九五，咸其脢，无悔。 象曰：“咸其脢”，志末也。”">​</a></h3><p>九五处悦之中，未免偏系之弊，故不能感人心，而曰“咸其脢”，惟圣人然后能感人心也。一无曰字。</p><h3 id="上六-咸其辅、颊、舌。-象曰-咸其辅、颊、舌-滕口说也。" tabindex="-1">上六，咸其辅、颊、舌。 象曰：“咸其辅、颊、舌”，滕口说也。 <a class="header-anchor" href="#上六-咸其辅、颊、舌。-象曰-咸其辅、颊、舌-滕口说也。" aria-label="Permalink to “上六，咸其辅、颊、舌。 象曰：“咸其辅、颊、舌”，滕口说也。”">​</a></h3>',16)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
